package io.github.jesterportfolio.hearth.persistence;
import java.sql.*;import java.util.*;import java.util.concurrent.*;import javax.sql.DataSource;
import io.github.jesterportfolio.hearth.economy.*;import io.github.jesterportfolio.hearth.inventory.*;
public final class MetadataPeerDatabaseChecks {
 static <T>T await(CompletionStage<T> f)throws Exception{return f.toCompletableFuture().get(10,TimeUnit.SECONDS);}
 static void check(boolean b,String label){if(!b)throw new IllegalStateException(label);System.out.println("HEARTH_METADATA_DB_CHECK PASS "+label);System.out.flush();}
 static void reject(CompletionStage<?> f)throws Exception{try{await(f);throw new IllegalStateException("EXPECTED_REJECTION");}catch(ExecutionException expected){}}
 public static void run(DataSource source,Connection c)throws Exception{var p=new Properties();try(var in=MetadataPeerDatabaseChecks.class.getResourceAsStream("/economy-demo.properties")){p.load(in);}p.setProperty("fixture-balance","0");var db=PostgresProgressStore.forModules(source,f->{});try{var economy=new EconomyStore(db,EconomyContent.parse(p));await(economy.migrate());UUID realm=UUID.randomUUID();await(economy.openNativeRealm(realm,UUID.randomUUID(),"b".repeat(64),1,true));var a=economy.context(realm,UUID.randomUUID());var b=economy.context(realm,UUID.randomUUID());var empty=InventoryPayload.pack(new byte[41][]);var first=await(economy.ensureAccount(a,empty));var second=await(economy.ensureAccount(b,empty));try(var st=c.prepareStatement("UPDATE hearth_economy.account SET balance=100 WHERE realm_id=?")){st.setObject(1,realm);st.executeUpdate();}
  var x=new byte[41][];x[0]=new byte[]{1,2};var afterA=InventoryPayload.pack(x);x[0]=new byte[]{3,4};var afterB=InventoryPayload.pack(x);var left=new PeerTrade.Offer(Map.of(),7,Map.of(0,new PeerTrade.Stack("a".repeat(64),1)));var right=new PeerTrade.Offer(Map.of(),3,Map.of(1,new PeerTrade.Stack("b".repeat(64),2)));UUID id=UUID.randomUUID();var req=new EconomyStore.PeerRequest(id,a,b,left,right);
  var one=economy.peer(req,first.inventory(),second.inventory(),afterA,afterB,()->true,EconomyStore.Probe.NONE);var two=economy.peer(req,first.inventory(),second.inventory(),afterA,afterB,()->true,EconomyStore.Probe.NONE);var r1=await(one);var r2=await(two);check(r1.replay()!=r2.replay(),"same_metadata_request_has_one_commit");var aa=await(economy.account(a));var bb=await(economy.account(b));check(aa.balance()==96&&bb.balance()==104&&aa.inventory().payload().equals(afterA)&&bb.inventory().payload().equals(afterB),"both_native_shadows_and_money_commit_together");check(await(economy.peerReceipt(a,id)).orElseThrow().firstOffer().contains("/slot:0:"),"metadata_slot_hash_is_in_immutable_receipt");reject(economy.peer(new EconomyStore.PeerRequest(id,a,b,new PeerTrade.Offer(Map.of(),7,Map.of(0,new PeerTrade.Stack("c".repeat(64),1))),right),first.inventory(),second.inventory(),afterA,afterB,()->true,EconomyStore.Probe.NONE));check(true,"same_request_cannot_change_metadata_or_quantity");
  var rollback=new EconomyStore.PeerRequest(UUID.randomUUID(),a,b,left,right);reject(economy.peer(rollback,aa.inventory(),bb.inventory(),empty,empty,()->true,EconomyStore.Probe.ROLLBACK));check(await(economy.account(a)).equals(aa)&&await(economy.account(b)).equals(bb),"SQL_failure_preserves_both_original_accounts");reject(economy.peer(rollback,first.inventory(),second.inventory(),empty,empty,()->true,EconomyStore.Probe.NONE));check(true,"stale_native_revisions_reject_without_replacing_originals");
  var unknown=new EconomyStore.PeerRequest(UUID.randomUUID(),a,b,left,right);reject(economy.peer(unknown,aa.inventory(),bb.inventory(),empty,empty,()->true,EconomyStore.Probe.COMMIT_UNKNOWN));var recovered=await(economy.peer(unknown,aa.inventory(),bb.inventory(),empty,empty,()->true,EconomyStore.Probe.NONE));check(recovered.replay()&&await(economy.account(a)).balance()==92&&await(economy.account(b)).balance()==108,"unknown_commit_is_receipt_replay_not_another_payment");reject(economy.peerReceipt(economy.context(realm,UUID.randomUUID()),id));check(true,"third_party_cannot_read_metadata_receipt");
 }finally{await(db.closeAsync());}}
}
